  for (i = 0; i < 16; i = i + 1) begin : g1
    assign s1[i] = a_i[2*i] + a_i[2*i+1];
  end
  for (i = 0; i < 8; i = i + 1) begin : g2
    assign s2[i] = s1[2*i] + s1[2*i+1];
  end
endgenerate
always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
