wire v0  = (ec^rc0)^uc0;
wire vc0 = (ec&rc0)|(uc0&(ec^rc0));

wire y2 = u0^gc;
wire y3 = v0^(u0&gc);
wire cw = v0&u0&gc;
wire y4 = vc0^cw;
wire y5 = vc0&cw;

wire [5:0] total = {y5,y4,y3,y2,y1,y0};

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= total;
    end
end
endmodule

